const item = $input.item.json;
const now = new Date();

function daysBetween(dateStr) {
  if (!dateStr) return null;
  const then = new Date(dateStr);
  return Math.floor((now.getTime() - then.getTime()) / 86400000);
}

const hasCrmRecord = item.crm_record_id !== null && item.crm_record_id !== undefined;
const daysSinceLastContact = daysBetween(item.last_contact_at);
const hasWebsite = !!item.website;
const enrichment = item.enrichment || {};
const raw = item.raw || {};
const emails = Array.isArray(enrichment.emails) ? enrichment.emails : [];
const hasEmail = !!item.candidate_email || emails.length > 0;
const hasLinkedin = !!item.linkedin_url;
const hasDescription = !!(enrichment.profile && enrichment.profile.description);
const googleRating = typeof raw.rating === 'number' ? raw.rating : null;
const followupCount = item.followup_count || 0;
const replyCount = item.reply_count || 0;
const priorityWeight = item.priority_weight || 5;
const hasManualActivity = !!(item.owner || (item.notes && item.notes.trim().length > 0));
const proposalStatus = item.proposal_status || null;
const draftStatus = item.draft_status || null;
const pipelineStage = hasCrmRecord ? item.pipeline_stage : null;
const legacyStage = hasCrmRecord ? item.legacy_stage : null;
const candidateStage = item.candidate_stage;

const factors = {};
factors.qualification = Math.round(((item.qualification_score || 0) / 100) * 25);
factors.segment_fit = Math.round((Math.min(priorityWeight, 10) / 10) * 7);
factors.website_quality = hasWebsite ? (hasDescription ? 6 : 4) : 0;
factors.email_availability = hasEmail ? 9 : 0;
factors.linkedin_availability = hasLinkedin ? 4 : 0;
factors.google_rating = googleRating !== null ? Math.round((googleRating / 5) * 4) : 0;
factors.followup_engagement = Math.min(followupCount * 2, 4);
factors.email_opens = 0;
factors.reply_history = replyCount > 0 ? 14 : 0;
factors.manual_crm_activity = hasManualActivity ? 4 : 0;
factors.business_potential = Math.round((Math.min(priorityWeight, 10) / 10) * 9);

const daysSinceChanged = daysBetween(item.candidate_last_changed);
let recency;
if (daysSinceLastContact === null) {
  recency = (daysSinceChanged !== null && daysSinceChanged <= 3) ? 6 : 3;
} else if (daysSinceLastContact <= 3) { recency = 10; }
else if (daysSinceLastContact <= 7) { recency = 7; }
else if (daysSinceLastContact <= 14) { recency = 4; }
else if (daysSinceLastContact <= 30) { recency = 2; }
else { recency = 0; }
factors.recency = recency;

const conversionScore = Object.values(factors).reduce(function (a, b) { return a + b; }, 0);
const conversionProbability = Math.round((conversionScore / 100) * 100) / 100;

let opportunityHealth = null;
if (!hasCrmRecord || ['Won', 'Lost', 'Repeat Customer'].indexOf(pipelineStage) === -1) {
  const d = daysSinceLastContact === null ? daysSinceChanged : daysSinceLastContact;
  if (d === null || d <= 7) { opportunityHealth = 'Healthy'; }
  else if (d <= 21) { opportunityHealth = 'At Risk'; }
  else { opportunityHealth = 'Stalled'; }
}

let newPipelineStage = pipelineStage;
let pipelineStageChanged = false;
let becameWon = false;
if (hasCrmRecord) {
  newPipelineStage = pipelineStage;
  if (candidateStage === 'disqualified' && ['Lost', 'Won'].indexOf(pipelineStage) === -1) {
    newPipelineStage = 'Lost';
  } else if (legacyStage === 'lost' && ['Lost', 'Won'].indexOf(pipelineStage) === -1) {
    newPipelineStage = 'Lost';
  } else if (proposalStatus === 'accepted' && pipelineStage !== 'Won') {
    newPipelineStage = 'Won';
  } else if (proposalStatus === 'sent' && ['New', 'Qualified', 'Contacted', 'Interested'].indexOf(pipelineStage) !== -1) {
    newPipelineStage = 'Proposal Sent';
  } else if (replyCount > 0 && ['New', 'Qualified', 'Contacted'].indexOf(pipelineStage) !== -1) {
    newPipelineStage = 'Interested';
  }
  pipelineStageChanged = newPipelineStage !== pipelineStage;
  becameWon = newPipelineStage === 'Won' && pipelineStage !== 'Won';
}

const salesStage = hasCrmRecord ? newPipelineStage : 'Not in CRM';

let nextBestAction = null;
let nextBestActionReason = null;
if (hasCrmRecord && ['Won', 'Lost', 'Repeat Customer'].indexOf(salesStage) !== -1) {
  nextBestAction = null;
  nextBestActionReason = 'Opportunity closed';
} else if (!hasCrmRecord && !draftStatus) {
  nextBestAction = 'Send first email';
  nextBestActionReason = 'Qualified and not yet contacted';
} else if (draftStatus === 'draft') {
  nextBestAction = 'Send first email';
  nextBestActionReason = 'Outreach drafted but not yet sent';
} else if (replyCount > 0 && (!hasCrmRecord || ['New', 'Qualified', 'Contacted'].indexOf(salesStage) !== -1)) {
  nextBestAction = 'Call today';
  nextBestActionReason = 'Lead replied - call while interest is fresh';
} else if (replyCount > 0) {
  nextBestAction = 'Respond to reply';
  nextBestActionReason = 'Unanswered inbound reply detected';
} else if (proposalStatus === 'sent') {
  const daysSinceProposal = daysBetween(item.proposal_sent_at);
  if (daysSinceProposal !== null && daysSinceProposal > 7) {
    nextBestAction = 'Follow up on proposal';
    nextBestActionReason = 'Proposal sent over a week ago with no decision';
  } else {
    nextBestAction = 'Wait';
    nextBestActionReason = 'Proposal recently sent - awaiting response';
  }
} else if (proposalStatus === 'accepted') {
  nextBestAction = 'Convert to customer';
  nextBestActionReason = 'Proposal accepted';
} else if (draftStatus === 'sent' && daysSinceLastContact !== null && daysSinceLastContact < 3) {
  nextBestAction = 'Wait';
  nextBestActionReason = 'Recently contacted - give it time to land';
} else if (salesStage === 'Interested' && !proposalStatus) {
  nextBestAction = 'Schedule site inspection';
  nextBestActionReason = 'Interested lead needs an on-site assessment before quoting';
} else if (salesStage === 'Site Visit Scheduled') {
  nextBestAction = 'Send proposal';
  nextBestActionReason = 'Site visit complete - ready to quote';
} else if (hasCrmRecord && followupCount < 3 && daysSinceLastContact !== null && daysSinceLastContact >= 3) {
  nextBestAction = 'Follow up';
  nextBestActionReason = 'No response - due for next follow-up';
} else if (hasCrmRecord && daysSinceLastContact !== null && daysSinceLastContact > 30) {
  nextBestAction = 'Mark lost';
  nextBestActionReason = 'No activity for over 30 days';
} else {
  nextBestAction = 'Wait';
  nextBestActionReason = 'On track - no action due yet';
}

const proposalReadiness = (conversionScore >= 60 && !proposalStatus && (replyCount > 0 || salesStage === 'Interested' || salesStage === 'Site Visit Scheduled')) ? 'Ready' : 'Not Ready';
const customerReadiness = (proposalStatus === 'accepted') ? 'Ready' : 'Not Ready';
const estimatedValue = Math.round(Math.min(priorityWeight, 10) * 150 * 100) / 100;

return {
  json: {
    candidateId: item.candidate_id,
    crmRecordId: item.crm_record_id,
    hasCrmRecord: hasCrmRecord,
    businessName: item.business_name,
    address: item.address,
    conversionScore: conversionScore,
    conversionFactors: { version: 'conv_v1', factors: factors, total: conversionScore },
    conversionProbability: conversionProbability,
    nextBestAction: nextBestAction,
    nextBestActionReason: nextBestActionReason,
    opportunityHealth: opportunityHealth,
    proposalReadiness: proposalReadiness,
    customerReadiness: customerReadiness,
    estimatedValue: estimatedValue,
    oldPipelineStage: pipelineStage,
    newPipelineStage: newPipelineStage,
    pipelineStageChanged: pipelineStageChanged,
    becameWon: becameWon,
    isCustomer: !!item.is_customer,
    candidateUpdatedAt: item.candidate_last_changed
  }
};
